function defaultLeaveCycleStart(p){const c=db.companies?.find(c=>c.id===company);return /CIBTP|CNETP|Caisse.*BTP|coopératives/i.test(String(p.cibtp||c?.cibtp||''))?4:6;}
/* Automatisations visibles et réversibles, sans modifier les bulletins historiques. */
function previousLeaveRecord(p){const [y,m]=period().split('-').map(Number),prev=m===1?`${y-1}-12`:`${y}-${String(m-1).padStart(2,'0')}`;return db.vars[company+'|'+prev+'|'+p.id];}
function derivePreparation(v,strict=false){v={...v,preparationWarning:''};const run=fn=>{try{fn()}catch(e){if(strict)throw e;v.preparationWarning=e.message;}};if(v.cpHoursMode==='Calendrier'){run(()=>{const c=PayrollAutomation.calendar(v,v.leaveCurrentPeriod||period());if(!c.hasDates&&Number(v.cpDays)>0)throw Error('Renseignez les dates des congés pour calculer les heures.');v.cpLeaveHours=c.leaveHours.toFixed(2);v.cpActualHours=c.monthHours.toFixed(2);});}if(v.leaveAcquisitionMode==='Automatique')run(()=>{v.leaveAcquiredMonth=String(PayrollAutomation.acquisition(v));const ratio=v.cpUnit==='Ouvrés'?5/6:1;v.leaveSickAcquiredMonth=String(Math.max(0,Math.round(Math.min(Number(v.leaveAcquiredMonth),2*Number(v.leaveSickPercent||0)/100*ratio,24*ratio-Number(v.leaveSickAcquiredBefore||0))*1000000)/1000000));});return v;}
const beforePreparationAuto=autoVariables;
autoVariables=function(v){return beforePreparationAuto(derivePreparation(v,true));};
const beforePreparationRich=richVar;
richVar=function(p){const v=beforePreparationRich(p),saved=db.vars[vkey(p)]||{},previous=previousLeaveRecord(p);const legacyHours=saved.cpLeaveHours!==undefined&&saved.cpLeaveHours!=='';const illness=v.absenceType==='Maladie',otherAbsence=Number(v.absenceHours)>0||Number(v.ijss)>0||!['Aucune','Congés payés','AT / MP'].includes(v.absenceType);const partial=(p.startDate&&p.startDate.slice(0,7)===period()&&p.startDate.slice(-2)!=='01')||(p.actualEndDate&&p.actualEndDate.slice(0,7)===period()&&Number(p.actualEndDate.slice(-2))!==new Date(Number(period().slice(0,4)),Number(period().slice(5,7)),0).getDate());const d={cpHoursMode:legacyHours?'Manuel':'Calendrier',cpStart:v.absenceType==='Congés payés'?v.absenceStart:'',cpEnd:v.absenceType==='Congés payés'?v.absenceEnd:'',cpNonWorkedDates:'',leaveCycleStart:p.leaveCycleStart||previous?.leaveCycleStart||defaultLeaveCycleStart(p),leaveAcquisitionMode:'Automatique',leaveWorkedPercent:otherAbsence||partial?'':'100',leaveSickPercent:'0',leaveSickAcquiredBefore:'0',leaveCurrentPeriod:period(),csgMode:Number(v.csgExtra)>0?'Montant fourni':'Automatique',csgOtherExtra:'0',csgPriorGross:'',csgAnnualLimit:'192240'};const partTime=p.workMode==='Temps partiel';for(let i=0;i<7;i++)d['cpPlan'+i]=p['cpPlan'+i]??(previous?.['cpPlan'+i]??(i>0&&i<6?(partTime?'':((Number(p.weeklyHours)||35)/5).toFixed(2)):'0'));let out={...d,...v,...Object.fromEntries(Object.keys(d).filter(k=>saved[k]!==undefined).map(k=>[k,saved[k]])),leaveCurrentPeriod:period()};if(!Object.keys(saved).length&&previous){try{if(!p.leaveUnit)out.cpUnit=previous.cpUnit||out.cpUnit;if((previous.cpUnit||'Ouvrables')===out.cpUnit){out={...out,...PayrollAutomation.carry(previous,period(),out.leaveCycleStart),leaveAsOf:period()+'-01',leaveAcquisitionMode:'Automatique',leaveCycleStart:previous.leaveCycleStart||out.leaveCycleStart,leaveSickAcquiredBefore:Number(period().slice(5,7))===Number(out.leaveCycleStart)?'0':String(Number(previous.leaveSickAcquiredBefore||0)+Number(previous.leaveSickAcquiredMonth||0))};}}catch(e){out.leaveCarryNotice=e.message;}}out.leaveCycle=out.leaveCycle||PayrollAutomation.cycle(period(),out.leaveCycleStart);return derivePreparation(out);};
const beforePreparationMarkup=variableMarkup;
variableMarkup=function(p){const v=richVar(p),days=['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];let html=beforePreparationMarkup(p);html+=section('Congés · calcul automatique des heures',selectField('cpHoursMode','Calcul des heures de congés',v.cpHoursMode,['Calendrier','Manuel'])+field('cpStart','Congés — premier jour',v.cpStart,'date')+field('cpEnd','Congés — dernier jour inclus',v.cpEnd,'date')+days.map((day,i)=>field('cpPlan'+i,day+' — heures habituellement prévues',v['cpPlan'+i],'number','min="0" max="24" step=".01"')).join('')+field('cpNonWorkedDates','Jours non travaillés / fériés à exclure (AAAA-MM-JJ séparés par virgules)',v.cpNonWorkedDates)+`<p class="wide notice" id="calendarLive" aria-live="polite"></p><p class="wide muted">Le planning lundi–vendredi est proposé pour un temps plein et doit correspondre au contrat. Temps partiel : répartition à renseigner. Les heures sont comptées uniquement dans le mois sélectionné ; week-ends travaillés pris en compte selon le planning. Les jours fériés et autres jours non travaillés sont à préciser. Les compteurs de droits restent en jours, sans conversion automatique en droits horaires.</p>`);
html+=section('Congés N · report et acquisition mensuelle',selectField('leaveAcquisitionMode','Acquisition des droits de ce mois',v.leaveAcquisitionMode,['Automatique','Manuelle'])+field('leaveCycleStart','Mois de début du cycle (1 à 12 ; 4 = avril, 6 = juin)',v.leaveCycleStart,'number','min="1" max="12" step="1"')+field('leaveWorkedPercent','Part du mois travail / absence assimilée (%)',v.leaveWorkedPercent,'number','min="0" max="100" step=".0001"')+field('leaveSickPercent','Part du mois en maladie non professionnelle (%)',v.leaveSickPercent,'number','min="0" max="100" step=".0001"')+field('leaveSickAcquiredBefore','Droits N déjà acquis pour maladie non professionnelle (jours, même unité)',v.leaveSickAcquiredBefore,'number','min="0" step=".000001"')+`<input type="hidden" name="leaveCurrentPeriod" value="${esc(period())}"><p class="wide notice" id="acquisitionLive" aria-live="polite"></p><p class="wide muted">Mois complet travaillé / assimilé : 2,5 jours ouvrables ; maladie non professionnelle : 2 jours ouvrables, sous plafond annuel de 24 pour cette maladie. Plafond total ordinaire : 30 jours ouvrables (équivalent de 25 ouvrés). Un temps partiel conserve les mêmes droits en jours. Les fractions du mois, entrées/sorties, absences et droits maladie déjà acquis doivent être vérifiés ; le décompte par mois, quatre semaines ou jours équivalents le plus favorable et les règles conventionnelles restent à contrôler. Les fractions de jours sont conservées pour éviter l’accumulation d’arrondis ; arrondi de clôture proposé au dernier mois du cycle. Droits supplémentaires et règles plus favorables à intégrer en mode manuel. En CIBTP, rapprochez les droits du relevé de caisse.</p><p class="wide muted">${esc(v.leaveCarryNotice||'Nouveau mois : reprise automatique du mois précédent s’il est renseigné. Sinon, initialisez les compteurs N−1 et N. Un mois déjà enregistré conserve sa situation de départ ; le bouton de reprise permet une mise à jour volontaire.')}</p>`);
html+=section('CSG / CRDS · assiette calculée',selectField('csgMode','Complément d’assiette CSG',v.csgMode,['Automatique','Montant fourni'])+num('csgOtherExtra','Autres éléments à réintégrer à 100 % dans la CSG (€)',v.csgOtherExtra)+field('csgPriorGross','Brut éligible à l’abattement cumulé avant ce mois (€)',v.csgPriorGross,'number','min="0" step=".01"')+field('csgAnnualLimit','Limite annuelle d’abattement (4 PASS, 192 240 € en 2026)',v.csgAnnualLimit,'number','min="0" step=".01"')+`<p class="wide notice" id="csgBaseLive" aria-live="polite"></p><p class="wide muted">Base courante : brut après abattement de 1,75 % dans la limite applicable + éléments soumis à 100 %. En mode automatique, la part employeur des lignes marquées « Réintégrer dans la CSG : Oui » (ex. mutuelle/prévoyance selon leur régime) est ajoutée avec les autres éléments saisis. L’assiette est commune aux lignes CSG/CRDS. Cumuls annuels non fournis : plafond mensuel de test utilisé, base provisoire à contrôler. Les régimes particuliers et exonérations restent à traiter séparément.</p>`);return html;};
const beforePreparationRows=rowMarkup;
rowMarkup=function(r){r=r||{label:'',baseMode:'gross',base:'0',employeeRate:'0',employerRate:'0'};return beforePreparationRows(r).replace('</div>',selectField('cotCsgInclude','Réintégrer la part employeur dans la CSG',r.csgInclude||'À vérifier',['À vérifier','Non','Oui'])+'</div>');};
const beforePreparationRead=readVariableForm;
readVariableForm=function(f){const raw=derivePreparation(Object.fromEntries(f),true);for(const k of ['cpLeaveHours','cpActualHours','leaveAcquiredMonth','leaveSickAcquiredMonth'])if(raw[k]!==undefined)f.set(k,raw[k]);const v=beforePreparationRead(f);const flags=f.getAll('cotCsgInclude');v.rows.forEach((r,i)=>r.csgInclude=flags[i]||'À vérifier');v.csgMode=f.get('csgMode');v.csgOtherExtra=f.get('csgOtherExtra');if(v.csgMode==='Automatique'){const input=engineInput(v);v.csgExtra=input.csgExtra;}return v;};
const beforePreparationEngine=engineInput;
engineInput=function(v){return PayrollAutomation.csgInput(v,beforePreparationEngine(v));};
const beforePreparationRefresh=refreshCalculations;
refreshCalculations=function(){const f=$('#form');if(!f.querySelector('[name=cpHoursMode]'))return beforePreparationRefresh();for(const k of ['cpLeaveHours','cpActualHours'])f.elements[k].readOnly=f.elements.cpHoursMode.value==='Calendrier';f.elements.leaveAcquiredMonth.readOnly=f.elements.leaveAcquisitionMode.value==='Automatique';try{const v=derivePreparation(Object.fromEntries(new FormData(f)),true);for(const k of ['cpLeaveHours','cpActualHours','leaveAcquiredMonth']){f.elements[k].value=v[k]??'';f.elements[k].readOnly=k==='leaveAcquiredMonth'?v.leaveAcquisitionMode==='Automatique':v.cpHoursMode==='Calendrier';}f.elements.csgExtra.readOnly=v.csgMode==='Automatique';$('#formError').textContent='';beforePreparationRefresh();$('#calendarLive').textContent=`Heures de congés du mois : ${v.cpLeaveHours||'à compléter'} h · heures prévues dans le mois : ${v.cpActualHours||'à compléter'} h.`;$('#acquisitionLive').textContent=`Acquisition du mois : ${v.leaveAcquiredMonth||0} jours. ${v.leaveCarryNotice||''}`;try{const full=readVariableForm(new FormData(f)),input=engineInput(full);const r=PayrollTest.calculate({...input,taxableNet:'0',socialNet:'',pasRate:'0',advance:'0',otherDeduction:'0'});if(full.csgMode==='Automatique')f.elements.csgExtra.value=input.csgExtra;const base=PayrollTest.csgBase(r.gross,input.csgExtra||0,input.csgAbatementRoom??Number(input.ceiling||4005)*4);$('#csgBaseLive').textContent=`Assiette CSG / CRDS : ${euroFmt(base)} · brut ${euroFmt(r.gross)} · compléments à 100 % ${euroFmt(input.csgExtra||0)}.${full.csgPriorGross===''?' Cumul annuel à renseigner pour vérifier la limite d’abattement.':''}${full.rows.some(r=>r.csgInclude==='À vérifier')?' Certaines lignes de cotisation restent à qualifier pour la réintégration.':''}`;}catch(e){$('#csgBaseLive').textContent=e.message;}}catch(e){$('#calendarLive').textContent=e.message;$('#acquisitionLive').textContent=e.message;$('#grossLive').textContent='À compléter';$('#formError').textContent=e.message;}};
const beforePreparationCopy=copyPreviousLeave;
copyPreviousLeave=function(id){try{const p=people().find(p=>p.id===id),prev=previousLeaveRecord(p);if(!prev)throw Error('Aucun compteur enregistré au mois précédent.');const f=$('#form');if((prev.cpUnit||'Ouvrables')!==f.elements.cpUnit.value)throw Error('Les unités de congés diffèrent : vérifiez la reprise.');const c=PayrollAutomation.carry(prev,period(),f.elements.leaveCycleStart.value);for(const k of ['leaveN1','leaveN','leaveTakenN1','leaveTakenN','leaveCycle'])f.elements[k].value=c[k];f.elements.leaveSickAcquiredBefore.value=Number(period().slice(5,7))===Number(f.elements.leaveCycleStart.value)?0:Number(prev.leaveSickAcquiredBefore||0)+Number(prev.leaveSickAcquiredMonth||0);f.elements.leaveAsOf.value=period()+'-01';refreshCalculations();toast(c.leaveCarryNotice);}catch(e){toast(e.message)}};

const beforePreparationEmployee=employee;
employee=function(id){beforePreparationEmployee(id);const p=db.people.find(p=>p.id===id)||{},partTime=p.workMode==='Temps partiel',days=['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];$('#formError').insertAdjacentHTML('beforebegin',section('Planning hebdomadaire de référence pour les congés',days.map((day,i)=>field('cpPlan'+i,day+' — heures habituelles',p['cpPlan'+i]??(i>0&&i<6?(partTime?'':((Number(p.weeklyHours)||35)/5).toFixed(2)):'0'),'number','min="0" max="24" step=".01"')).join('')+field('leaveCycleStart','Mois de début du cycle de congés (1 à 12)',p.leaveCycleStart||defaultLeaveCycleStart(p),'number','min="1" max="12" step="1"')+`<p class="wide muted">Planning à adapter au contrat. Il initialise le calcul des heures dans la préparation mensuelle. Aucun droit à congé n’est diminué au seul motif d’un temps partiel.</p>`));};
render();

const beforePreparationShowDraft=showDraft;
showDraft=function(id){beforePreparationShowDraft(id);const tools=$('#form .no-print .tools');if(!tools)return;const button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='Recalculer depuis la préparation enregistrée';button.onclick=()=>{const old=db.bulletins.find(d=>d.id===id);if(!old||!people().some(p=>p.id===old.personId)){toast('Fiche salarié introuvable pour cette entreprise.');return;}if(old.period!==period()){toast('Sélectionnez la période '+old.period+' pour actualiser ce bulletin.');return;}$('#modal').close();createDraft(old.personId);};tools.appendChild(button);};
